let annualPricing=false;
function planFeatures(features){return `<ul class="plan-features">${features.map(t=>`<li>${icon('check',16)}<span>${t}</span></li>`).join('')}</ul>`}
function homepage(){const signed=typeof Account!=='undefined'&&Boolean(Account.user),start=signed?'overview':'signup',featured=jobs.filter(j=>j.demoCreator).slice(0,3);return `<div id="landing" class="home-redesign"><div class="home-nav"><a class="landing-brand" href="#home"><img src="assets/brand/nextwork-icon.png" alt="">nextwork</a><nav><a href="#explore">Find work</a><a href="#organization">For organizations</a><a href="#pricing">Free membership</a></nav><div>${signed?`<a class="primary" href="#overview">Open workspace ${icon('arrow',16)}</a>`:`<a class="home-login" href="#login">Log in</a><a class="primary" href="#signup">Join Nextwork ${icon('arrow',16)}</a>`}</div></div><section class="home-hero"><div class="home-hero-copy"><span class="hero-eyebrow"><span></span> YOUR NEXT CHAPTER STARTS HERE</span><h1>Real work.<br>Real experience.<br><em>Your next move.</em></h1><p>Connect with startups and small teams. Take on meaningful projects and build experience that opens doors.</p><div class="home-hero-actions"><a class="primary" href="#${start}">${signed?'Open your workspace':'Find your first opportunity'} ${icon('arrow',18)}</a><a class="home-hero-secondary" href="#organization">Looking to hire? ${icon('arrow',16)}</a></div><small>Free to join. Free to apply. No card required.</small></div><div class="home-opportunity-board"><div class="home-board-top"><span><i></i> GOOD WORK IS OUT THERE</span><b>Find your place.</b></div>${jobs.filter(j=>j.id===7||j.id===3||j.id===9).map((j,i)=>`<a class="home-opportunity ${i===0?'featured':''}" href="#project/${j.id}"><div>${logo(j)}<span><b>${esc(j.c)}</b><small>${esc(j.cat)} · Remote</small></span><em>$${j.pay.toLocaleString()}</em></div><h3>${esc(j.title)}</h3><div><span class="home-board-skill">${esc(j.tags[0])}</span><span>${esc(j.weeks)}</span>${icon('arrow',16)}</div></a>`).join('')}<span class="home-board-note">Clear deliverables. A real contribution.</span></div></section><div class="home-value-strip"><span>${icon('briefcase',20)} Paid, scoped opportunities</span><span>${icon('resume',20)} Resume matching that makes sense</span><span>${icon('message',20)} Direct conversations</span><span>${icon('spark',20)} Room to build and grow</span></div><section class="home-section" id="how-it-works"><div class="home-section-heading"><div><span class="section-label">FROM POTENTIAL TO PROOF</span><h2>Your first step shouldn’t<br>be the hardest one.</h2></div><p>A simple way to find work, show what you can do, and move your career forward.</p></div><div class="home-how-grid">${[['01','user','Show what you bring','Create a profile and add your resume. Help teams understand your experience.'],['02','briefcase','Find the right work','Explore opportunities with clear expectations and see how your resume fits.'],['03','arrow','Make your contribution','Meet the team, take on a project, and build something you can talk about.']].map(([n,i,t,d])=>`<article><div><span>${n}</span>${icon(i,25)}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="home-section home-featured"><div class="home-section-heading"><div><span class="section-label">SMALL TEAMS. REAL POSSIBILITIES.</span><h2>Good work starts<br>with a good opportunity.</h2></div><a class="outline" href="#explore">Explore opportunities ${icon('arrow',16)}</a></div><div class="home-featured-grid">${featured.map(j=>`<a class="home-featured-job" href="#project/${j.id}"><div>${logo(j)}<span>${esc(j.c)}<small>${esc(j.sector)}</small></span></div><h3>${esc(j.title)}</h3><p>${esc(j.desc)}</p><div class="tags">${j.tags.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><footer><b>$${j.pay.toLocaleString()}</b><span>${esc(j.weeks)} ${icon('arrow',16)}</span></footer></a>`).join('')}</div></section><section class="home-membership" id="pricing"><div><span class="hero-eyebrow">ONE PLAN. MORE POSSIBILITY.</span><h2>Everything you need.<br>One free membership.</h2><p>Finding your next step should be about your potential, not your subscription.</p><a class="primary" href="#${start}">${signed?'Open workspace':'Create your free account'} ${icon('arrow',17)}</a></div><ul>${['Browse and apply to projects','Match your resume to a role','Get practical project ideas','Connect with people and teams'].map(x=>`<li>${icon('check',18)} ${x}</li>`).join('')}<li class="home-membership-price"><strong>$0</strong><span>Free for everyone.<br>No hidden upgrade.</span></li></ul></section><section class="home-section home-faq"><div><span class="section-label">A FEW THINGS TO KNOW</span><h2>Before you make<br>your next move.</h2></div><div>${[['Is Nextwork free?','Yes. Every tool is included in one free plan. No payment card is required.'],['What kind of opportunities can I find?','Projects, contracts, and roles at startups and small teams. Check each listing for scope, compensation, and requirements.'],['Will a project lead to a full-time job?','It can start a working relationship, but future employment depends on the team and a separate hiring decision.'],['How does resume matching work?','We compare resume evidence with the listing’s criteria and field foundations. Missing evidence is a chance to improve your resume, not proof that you lack a skill.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="home-final"><span class="section-label">YOUR NEXT CHAPTER</span><h2>Start with what you can do.<br>Discover what comes next.</h2><a class="primary" href="#${start}">${signed?'Open workspace':'Get started free'} ${icon('arrow',17)}</a></section><div class="home-footer"><a class="landing-brand" href="#home"><img src="assets/brand/nextwork-icon.png" alt="">nextwork</a><span>Meaningful work. A stronger next step.</span><a href="#organization">For organizations</a></div></div>`}

function scrollLanding(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function setPricing(annual){annualPricing=annual;render();scrollLanding('pricing')}
